def truncate_float(number: float, n: int) -> float:
    """ Given a positive floating point number, it can be decomposed into
    and integer part (largest integer smaller than given number) and decimals
    (leftover part always smaller than 1).

    Truncate number in n decimal places. The returned number has n
    decimals. If n is 0 return the integer part.
    >>> truncate_float(3.5, 0)
    3.0
    >>> truncate_float(3.5, 1)
    3.5
    >>> truncate_float(3.5, 2)
    3.49
    >>> truncate_float(3.5, 3)
    3.499
    >>> truncate_float(3.5, 4)
    3.4999
    """
    if number > 0:
        if n < 0:
            return number

        if n == 0:
            return int(number)

        return number - (int(number * (10 ** n))) / (10 ** n)
    else:
        if n < 0:
            return number

