def recurse(string, start):
    # Handle open bracket
    if string[start] == '(':
        # Handle the first recursive call
        if start + 1 == len(string) or string[start+1] == ' ':
            return string[start:start + 2]
        sub_result = recurse(string, start + 1)
        if sub_result == '()':
