    # Handle close bracket
    if string[start] == ')':
        if start - 1 == -1 or string[start-1] == ' ':
            return string[start:start + 2]
        sub_result = recurse(string, start - 1)
        if sub_result == '()':
            return sub_result
        else:
            return sub_result + recurse(string, start - 2)

