    """
    Calculate the total number of times it's possible to do the job.
    Example:
    >>> solution([1,2],[3,4],5)
    [0, 2]
    """
    if not (A and B):
        return [0, 0]
    if D >= max(A+B):
        return [len(B), 0]
    start, stop = 0, 0
    for i in range(len(B)):
        if B[i] < A[0]:
            continue
        start = i
        while stop + 1 < len(B) and B[stop + 1] - B[i] <= D:
            stop += 1
        if B[stop] - B[i] <= D:
            stop += 1
        if i > 0:
            for j in range(i):
                B[j] += D
    return [start, stop]

